import { readFileSync } from 'node:fs';

export function isEnabled(key) {
  try {
    const { flags } = JSON.parse(readFileSync(new URL('../flags.json', import.meta.url), 'utf8'));
    return flags[key] === true;
  } catch {
    return false;
  }
}

